// Datos originales del webhook + resumen de la IA (nodo anterior)
const wh = $('Webhook - Transcript').item.json;
const p = wh.body ?? wh;
const resumen = ($json.output || '').toString().trim();

const dialogo = Array.isArray(p.dialogo) ? p.dialogo : [];
const participantes = Array.isArray(p.participantes)
  ? p.participantes.join(', ')
  : (p.participantes || '');

// Duración HH:MM:SS
const dur = Number(p.duracion_seg || 0);
const hh = String(Math.floor(dur / 3600)).padStart(2, '0');
const mm = String(Math.floor((dur % 3600) / 60)).padStart(2, '0');
const ss = String(dur % 60).padStart(2, '0');
const durStr = `${hh}:${mm}:${ss}`;

// Fecha en hora de Argentina para el documento
let fechaLocal = p.fecha;
try {
  fechaLocal = new Date(p.fecha).toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' });
} catch (e) {}

// Diálogo en markdown
const dialogoMd = dialogo
  .map(d => `**[${d.t}] ${d.hablante}:** ${d.texto}`)
  .join('\n\n');

const md = `# ${p.titulo}

- **Canal:** ${p.canal}
- **Fecha:** ${fechaLocal}
- **Duración:** ${durStr}
- **Participantes:** ${participantes}

## Resumen

${resumen}

## Transcripción

${dialogoMd}
`;

// Nombre de archivo seguro (sin tildes ni símbolos)
const filename = (p.titulo || 'reunion').toString()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-zA-Z0-9-_ ]/g, '').trim()
  .replace(/\s+/g, '_').slice(0, 80) + '.md';

const file_base64 = Buffer.from(md, 'utf8').toString('base64');

// Texto plano para el campo Transcripción
const textoCompleto = p.texto_completo
  || dialogo.map(d => `[${d.t}] ${d.hablante}: ${d.texto}`).join('\n');

// Body para crear el registro en Airtable
const airtable_body = {
  fields: {
    "Título": p.titulo,
    "Fecha": p.fecha,
    "Canal": p.canal,
    "Participantes": participantes,
    "Duración": dur,
    "Resumen": resumen,
    "Transcripción": textoCompleto,
    "Estado": "Completo"
  },
  typecast: true
};

// Body para subir el adjunto .md (la URL usa el id del registro recién creado)
const upload_body = {
  contentType: "text/markdown",
  filename: filename,
  file: file_base64
};

return [{ json: { filename, airtable_body, upload_body } }];
